  <div v-if="state.records.length" class="table-scroll"><table class="ledger-table"><thead><tr><th>標的 / 幣別</th><th>股數</th><th>剩餘成本</th><th>已實現</th><th>估值 / 日期</th><th>未實現</th></tr></thead><tbody><tr v-for="p in calculation.positions" :key="p.ticker+p.currency"><th>{{ p.ticker }} / {{ p.currency }}</th><td>{{ number(p.quantity) }}</td><td>{{ number(p.cost_basis) }}</td><td>{{ number(p.realized) }}</td><td>{{ p.quote_price===null?'尚未估值':number(p.quote_price)+' / '+p.quote_date }}</td><td>{{ p.unrealized===null?'缺手動價格':number(p.unrealized) }}</td></tr></tbody></table></div>
