 <details v-if="mode==='management'" class="backup-panel" open><summary>備份、還原與清空</summary><button :disabled="busy || clearDependencies.length>0 || !state.records.length && !state.quotes.length && !state.reviews.length && !state.finance?.events.length && !state.finance?.prices.length && !state.finance?.fx.length && !state.finance?.valuations.length && !state.finance?.benchmark.length && !state.imports?.length" @click="clearLedger">備份並清空交易與資金</button><p v-if="clearDependencies.length" class="canonical-alert">{{ clearDependencies.length }} 個成交帳本標的仍有決策紀錄引用，清空已停用，以保留理由與回顧。請使用完整備份與還原管理；撤回紀錄也會保留引用。</p><p class="muted">清空後交易、價格、資金、估值、CSV批次與交易回顧為空；觀察決定、比較與重新核對保留。清空前版本保留於歷史，也會準備可複製及下載的備份。</p><p>下載含交易、持倉快照、公司收藏、估值、回顧及觀察／比較／核對的完整 JSON 備份，包含決策理由、回顧、截圖新增批次、月度研究、三情境與人工規則。還原先檢查格式、報告版本與整帳股數；套用時取代全部私人記錄，原資料先準備備份內容，請自行複製或下載保存。</p><div class="button-row"><button @click="downloadBackup">下載私人帳本備份</button><button @click="backupPreview=serializeBackup(state)">顯示可複製的備份內容</button></div><div v-if="backupPreview"><label>私人資料備份（可複製）<textarea :value="backupPreview" readonly rows="8" spellcheck="false" /></label><p class="muted">這是按鈕產生時的完整備份；請複製保存。清空或還原前會更新為原資料。</p><button @click="backupPreview=''">關閉備份內容</button></div><label>選擇備份檔<input type="file" accept="application/json,.json" @change="inspectBackup"/></label><details><summary>或貼上備份內容</summary><label>備份 JSON 內容<textarea v-model="backupText" maxlength="2000000" rows="5" /></label><button :disabled="!backupText.trim()" @click="inspectTextBackup">檢查貼上的備份</button></details><p v-if="restoreCandidate">待還原：{{ restoreCandidate.snapshots?.length || 0 }} 個持倉快照、{{ restoreCandidate.company_favorites?.length || 0 }} 家收藏、{{ restoreCandidate.records.length }} 筆交易、{{ restoreCandidate.quotes.length }} 個價格、{{ restoreCandidate.reviews.length }} 筆回顧、{{ restoreCandidate.research?.observations.length || 0 }} 筆觀察、{{ restoreCandidate.research?.comparisons.length || 0 }} 組比較、{{ restoreCandidate.research?.checks.length || 0 }} 筆核對、{{ restoreCandidate.finance?.events.length || 0 }} 筆資金事件、{{ restoreCandidate.finance?.prices.length || 0 }} 筆當日價格、{{ restoreCandidate.finance?.fx.length || 0 }} 筆匯率、{{ restoreCandidate.finance?.valuations.length || 0 }} 筆總估值、{{ restoreCandidate.finance?.benchmark.length || 0 }} 筆基準、{{ restoreCandidate.imports?.length || 0 }} 批 CSV。這會取代全部目前私人資料。</p><div v-if="restoreImpact" class="restore-impact"><p>新增決策資料：目前 {{ restoreImpact.before.positions }} 個部位、{{ restoreImpact.before.entries }} 筆理由／回顧／證據、{{ restoreImpact.before.intakes }} 個新增批次；還原後 {{ restoreImpact.after.positions }} 個部位、{{ restoreImpact.after.entries }} 筆理由／回顧／證據、{{ restoreImpact.after.intakes }} 個新增批次。</p><p v-if="restoreImpact.missing_journal" role="alert" class="canonical-alert">這份舊備份不含新增決策資料。套用後，上述目前的新增理由、回顧、證據與批次將不在目前帳本中；先保存完整備份才能復原。</p></div><div v-if="researchImpact" class="restore-impact"><p>月度研究／情境／人工規則：目前 {{ researchImpact.before.reviews }}／{{ researchImpact.before.scenarios }}／{{ researchImpact.before.rules }} 個版本；還原後 {{ researchImpact.after.reviews }}／{{ researchImpact.after.scenarios }}／{{ researchImpact.after.rules }} 個版本。</p><p v-if="researchImpact.missing_workspace || researchImpact.removes_versions" role="alert">此備份會取代部分目前研究版本；請先保存完整備份，原帳本仍保留在歷史。</p></div><button v-if="restoreCandidate" :disabled="busy" @click="restore">先備份目前帳本並套用還原</button><button v-if="restoreCandidate" @click="restoreCandidate=null">取消還原</button></details>
 <p class="muted">{{ savedAt?'最近儲存 '+savedAt:'尚未建立任何私人交易資料' }} · 不含即時行情或換匯。</p>
 </template>
</section>
</template>
<script setup>
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import {loadLedger,loadLedgerVersion,saveLedger} from './ledger-store.js'
import {replayLedger,validateRecord} from './ledger-core.mjs'
import {validateState} from '../worker/index.mjs'
import ReviewInsights from './ReviewInsights.vue'
import SnapshotList from './SnapshotList.vue'
import {splitEvents,emptyFinance} from './portfolio-core.mjs'
import {digest,copy,confirmsSavedChange} from './decision-workspace.mjs'
import {serializeBackup,parseBackup,ledgerClearDependencies,journalRestoreImpact,researchRestoreImpact} from './ledger-backup.mjs'
import {siteIndex} from './api.js'
const props=defineProps({mode:{type:String,default:'manual'},active:Boolean})
defineEmits(['navigate'])
let restoreContext=null,formBase=null
const captureBase=()=>({revision:revision.value,scope:scope.value})
const backupPreview=ref(''),backupText=ref(''),scope=ref(''),storage=ref(''),origin=location.host
let loadSequence=0,historySequence=0,pendingRecheck=false
const history=ref([]),oldState=ref(null),selectedRecordId=ref(new URLSearchParams(location.search).get('record')||'')
const loaded=ref(false),loading=ref(false),busy=ref(false),error=ref(''),message=ref(''),authRequired=ref(false),savedAt=ref(null),revision=ref(0),state=ref({schema_version:1,records:[],quotes:[],reviews:[]}),reports=ref([]),form=ref(null),reviewForm=ref(null),restoreCandidate=ref(null)
defineExpose({dirty:computed(()=>!!form.value||!!reviewForm.value)});
const date=()=>new Date().toISOString().slice(0,10)
const quote=ref({ticker:'',currency:'USD',price:'',date:date()})
const clearDependencies=computed(()=>ledgerClearDependencies(state.value)),restoreImpact=computed(()=>restoreCandidate.value?journalRestoreImpact(state.value,restoreCandidate.value):null),researchImpact=computed(()=>restoreCandidate.value?researchRestoreImpact(state.value,restoreCandidate.value):null)
const calculation=computed(()=>replayLedger(state.value.records,state.value.quotes,state.value.finance?splitEvents(state.value.finance):[]))
const activeRecords=computed(()=>state.value.records.filter(r=>r.status==='active').sort((a,b)=>b.date.localeCompare(a.date)))
const displayedRecords=computed(()=>[...state.value.records].sort((a,b)=>b.date.localeCompare(a.date)||b.created_at.localeCompare(a.created_at)))
const reviewRecords=computed(()=>{const id=selectedRecordId.value;return id?state.value.records.filter(r=>r.id===id):activeRecords.value})
const reviewTicker=computed(()=>state.value.records.find(r=>r.id===reviewForm.value?.record_id)?.ticker)
const number=v=>Number(v).toLocaleString('en-US',{maximumFractionDigits:12})
const reportUrl=id=>'?workspace=company&bundle='+encodeURIComponent(id)+'&researchTab=report'
const outcomeLabel=v=>({pending:'待觀察',supported:'支持原判斷',weakened:'削弱原判斷',mixed:'結果混合'}[v])
function discard(){historySequence++;loaded.value=false;state.value={schema_version:1,records:[],quotes:[],reviews:[]};revision.value=0;savedAt.value=null;history.value=[];oldState.value=null;form.value=null;reviewForm.value=null;restoreCandidate.value=null;backupText.value='';backupPreview.value='';quote.value={ticker:'',currency:'USD',price:'',date:date()};message.value='';scope.value='';storage.value=''}
function fail(e){if(e.status===401 || e.code==='identity_changed')discard();error.value=e.message;authRequired.value=e.status===401}
async function load(){const sequence=++loadSequence,previousScope=scope.value;loaded.value=false;loading.value=true;error.value='';authRequired.value=false;try{const data=await loadLedger();if(sequence!==loadSequence)return;if(previousScope && previousScope!==data.owner_scope)discard();scope.value=data.owner_scope;storage.value=data.storage;state.value=data.state;revision.value=data.revision;savedAt.value=data.updated_at;history.value=data.history||[];loaded.value=true}catch(e){if(sequence===loadSequence){discard();fail(e)}}finally{if(sequence===loadSequence)loading.value=false}}
async function recheckDraft(){const expected=scope.value;await load();if(loaded.value&&scope.value===expected&&!error.value){if(form.value||reviewForm.value)formBase=captureBase();message.value='已載入最新資料。草稿保留，請核對後再次明確保存；備份還原須重新檢查。';}}
async function commit(candidate,text,base=captureBase(),options={}){
 if(base.revision!==revision.value||base.scope!==scope.value){error.value='其他分頁已更新資料，請載入最新後重新核對原草稿。';return false;}
 if(busy.value||!loaded.value||!scope.value)return false;
 const checked=validateState(candidate);if(!checked.ok){error.value=checked.errors.map(e=>e.message).join('；');return false;}
 busy.value=true;error.value='';message.value='';const expectedScope=scope.value,sequence=loadSequence,before=copy(state.value);
 const accept=data=>{if(sequence!==loadSequence||scope.value!==expectedScope)return false;if(data.owner_scope!==expectedScope){discard();error.value='登入身份已改變，請重新載入。';return false;}state.value=data.state;revision.value=data.revision;savedAt.value=data.updated_at;history.value=data.history||history.value;message.value=text;error.value='';window.dispatchEvent(new Event('private-state-saved'));return true;};
 try{const data=await saveLedger(base.revision,checked.value,expectedScope,options);return accept(data);}
 catch(e){if(sequence!==loadSequence||scope.value!==expectedScope)return false;
  if(!e.status){error.value='保存結果待確認，正在讀回核對。';try{const latest=await loadLedger();if(sequence!==loadSequence||scope.value!==expectedScope)return false;if(latest.owner_scope!==expectedScope){discard();return false;}if(confirmsSavedChange(before,checked.value,latest.state))return accept(latest);state.value=latest.state;revision.value=latest.revision;history.value=latest.history||[];error.value='尚未確認保存。草稿保留，請載入最新後重新核對，再保存。';}catch(readError){fail(readError);}return false;}
  fail(e);return false;
 }finally{busy.value=false;if(pendingRecheck){pendingRecheck=false;load();}}
}
async function saveExchange({id,exchange}){if(!exchange)return;await commit({...state.value,snapshots:(state.value.snapshots||[]).map(s=>s.id===id?{...s,exchange}:s)},'交易所已儲存。')}
async function clearLedger(){if(!loaded.value)return;if(clearDependencies.value.length){error.value='成交帳本仍被決策紀錄引用，未清空任何資料。請先保存完整備份，再核對還原範圍。';return;}downloadBackup();if(await commit({...state.value,records:[],quotes:[],reviews:[],...(state.value.finance?{finance:emptyFinance()}:{}),...(state.value.imports?{imports:[]}: {})},'交易帳本已清空；觀察與比較保留。清空前備份內容已準備，歷史版本可還原。')){form.value=null;reviewForm.value=null;restoreCandidate.value=null;oldState.value=null;backupText.value='';quote.value={ticker:'',currency:'USD',price:'',date:date()}}}
function newRecord(){formBase=captureBase();error.value='';const p=new URLSearchParams(location.search);form.value={id:'',date:date(),ticker:p.get('ticker')||'',side:'BUY',quantity:'',price:'',currency:'USD',fees:0,reason:'',horizon:'',expectation:'',risk:'',invalidation:'',report_id:p.get('report')||'',links:''}}
function edit(r){formBase=captureBase();form.value={...r,links:r.source_links.join('\n')};window.scrollTo({top:0,behavior:'instant'})}
async function submit(){const now=new Date().toISOString(),f=form.value,raw={...f,id:f.id||crypto.randomUUID(),ticker:f.ticker.trim().toUpperCase(),currency:f.currency.trim().toUpperCase(),quantity:Number(f.quantity),price:Number(f.price),fees:Number(f.fees),source_links:f.links.split('\n').map(s=>s.trim()).filter(Boolean),status:f.status||'active',revision:(f.revision||0)+1,created_at:f.created_at||now,updated_at:now};delete raw.links;const check=validateRecord(raw);if(!check.ok){error.value=check.errors.map(e=>e.message).join('；');return}f.id=raw.id;const records=state.value.records.filter(r=>r.id!==raw.id);records.push(check.value);if(await commit({...state.value,records},'交易與決策已儲存。',formBase))form.value=null}
async function toggle(r){const now=new Date().toISOString(),records=state.value.records.map(x=>x.id===r.id?{...x,status:r.status==='active'?'withdrawn':'active',revision:r.revision+1,updated_at:now}:x);await commit({...state.value,records},r.status==='active'?'交易已撤回，紀錄仍可恢復。':'交易已恢復。')}
async function saveQuote(){const q={ticker:quote.value.ticker.trim().toUpperCase(),currency:quote.value.currency.trim().toUpperCase(),price:Number(quote.value.price),date:quote.value.date};const quotes=state.value.quotes.filter(v=>!(v.ticker===q.ticker&&v.currency===q.currency));quotes.push(q);if(await commit({...state.value,quotes},'手動估值價格已儲存。'))quote.value={ticker:'',currency:'USD',price:'',date:date()}}
async function removeQuote(q){await commit({...state.value,quotes:state.value.quotes.filter(v=>!(v.ticker===q.ticker&&v.currency===q.currency))},'估值價格已移除。')}
function startReview(r){formBase=captureBase();reviewForm.value={id:'',record_id:r.id,date:date(),outcome:'pending',lesson:'',next_action:''};setTimeout(()=>document.querySelector('.form-panel')?.scrollIntoView(),0)}
function editReview(r){formBase=captureBase();reviewForm.value={...r};setTimeout(()=>document.querySelector('.form-panel')?.scrollIntoView(),0)}
async function submitReview(){const r={...reviewForm.value,id:reviewForm.value.id||crypto.randomUUID()},reviews=state.value.reviews.filter(v=>v.id!==r.id);reviews.push(r);if(await commit({...state.value,reviews},'決策回顧已儲存。',formBase))reviewForm.value=null}
function downloadBackup(){backupPreview.value=serializeBackup(state.value);const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([backupPreview.value],{type:'application/json'}));a.download='investment-ledger-'+date()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function readHistory(v){const historyRequest=++historySequence;oldState.value=null;if(!v)return;try{const expectedScope=scope.value,sequence=loadSequence,data=await loadLedgerVersion(v);if(historyRequest!==historySequence || expectedScope!==scope.value || sequence!==loadSequence || !loaded.value)return;if(data.owner_scope!==expectedScope){discard();throw new Error('登入身份已改變，請重新載入。')}oldState.value=data}catch(e){fail(e)}}
function prepareHistoryRestore(){restoreCandidate.value=oldState.value.state;restoreContext={revision:revision.value,scope:scope.value};message.value='歷史版本已放入還原預覽；請展開「備份與還原」核對並套用。'}

function inspectTextBackup(){restoreCandidate.value=null;error.value='';try{restoreCandidate.value=parseBackup(backupText.value);restoreContext={revision:revision.value,scope:scope.value}}catch(e){fail(e)}}
async function inspectBackup(e){restoreCandidate.value=null;error.value='';const file=e.target.files[0];if(!file)return;try{if(file.size>2000000)throw new Error('備份超過 2 MB 限制。');const expectedScope=scope.value,sequence=loadSequence,text=await file.text();if(expectedScope!==scope.value || sequence!==loadSequence || !loaded.value)return;restoreCandidate.value=parseBackup(text);restoreContext={revision:revision.value,scope:scope.value}}catch(e){fail(e)}finally{e.target.value=''}}
async function restore(){if(!restoreContext||restoreContext.revision!==revision.value||restoreContext.scope!==scope.value){error.value='私人資料已更新，請重新檢查備份後再套用；這次沒有覆寫。';return}downloadBackup();if(await commit(restoreCandidate.value,'備份已還原；原帳本備份內容已準備，可複製或下載保存。',restoreContext,{intent:'restore',restore_base_digest:await digest(state.value)}))restoreCandidate.value=null}
function pop(){selectedRecordId.value=new URLSearchParams(location.search).get('record')||''}
function syncSaved(){if(!busy.value&&props.active)load()}
function recheck(){if(!props.active)return;if(busy.value){loaded.value=false;loadSequence++;pendingRecheck=true}else load()}
onUnmounted(()=>{window.removeEventListener('popstate',pop);window.removeEventListener('focus',recheck);window.removeEventListener('private-state-saved',syncSaved)})
onMounted(()=>{window.addEventListener('popstate',pop);window.addEventListener('focus',recheck);window.addEventListener('private-state-saved',syncSaved);load();siteIndex().then(v=>reports.value=v.catalog.bundles).catch(()=>{})})
watch(()=>props.active,v=>{if(v)recheck()})
</script>
